/* snprintf(3) - Safe formatted output to string */
#include <stdio.h>
#include <stdlib.h>

#define BUFFER_SIZE 25

int main(void) {
    char buffer[BUFFER_SIZE];
    int chars_needed;
    int temperature = 25;
    const char *unit = "Celsius";

    // Attempt to write a string that might exceed the buffer size
    chars_needed = snprintf(buffer, BUFFER_SIZE,
                            "The current temperature is %d degrees %s, which is quite mild.", 
                            temperature, unit);

    printf("Buffer size: %d\n", BUFFER_SIZE);
    printf("Characters needed (excluding null): %d\n", chars_needed);
    printf("Resulting string: '%s'\n", buffer);

    // Check if truncation occurred
    if (chars_needed < 0) {
        fprintf(stderr, "Error during string formatting.\n");
        return EXIT_FAILURE;
    } else if ((size_t)chars_needed >= BUFFER_SIZE) {
        // Truncation happened. The string in 'buffer' is safe but incomplete.
        printf("WARNING: Output truncated! Needed %d bytes.\n", chars_needed);
    } else {
        printf("Success: Full output written.\n");
    }

    return EXIT_SUCCESS;
}
